content:
[
  {
    "tag": "痛点开场型",
    "prompt": "请为{产品类型}写一篇小红书正文，开头用一句戳中{目标人群}痛点的话引入，正文分3段给出解决方案，每段不超过50字，结尾加一句行动号召，全文口语化。",
    "usage": "适合护肤、健身、学习类产品种草笔记",
    "example": "开头：熬夜党脸色暗黄真的没救了吗？正文三段分别讲成因、方法、坚持效果，结尾：姐妹们冲！"
  },
  {
    "tag": "清单合集型",
    "prompt": "请围绕{主题}写一篇小红书正文，用数字清单形式列出{数量}个{具体条目类型}，每条含一句标题加一句点评，正文开头加一句引导语，结尾提问互动。",
    "usage": "适合好物推荐、旅行攻略、书单影单类合集笔记",
    "example": "开头：整理了5个平价护肤好物，第3个回购3次！正文每条：①XX面霜——保湿不腻，结尾：你们最爱哪个？"
  },
  {
    "tag": "对比测评型",
    "prompt": "请为{产品A}和{产品B}写一篇小红书对比测评正文，分{对比维度1}、{对比维度2}、{对比维度3}三个维度对比，每维度一句结论，最后给出选购建议，语气客观中立。",
    "usage": "适合两款同类产品二选一的测评笔记",
    "example": "维度一价格：A更划算；维度二质地：B更轻薄；维度三持久度：A胜出；结论：预算有限选A。"
  },
  {
    "tag": "故事共鸣型",
    "prompt": "请以第一人称写一篇小红书正文，讲述我用{产品/方法}解决{具体问题}的真实经历，包含使用前困境、转折点、使用后变化三部分，每部分不超过60字，结尾分享感受。",
    "usage": "适合个人成长、健康改善、技能学习类笔记",
    "example": "使用前：每天加班到崩溃；转折：朋友推荐了XX；使用后：效率翻倍；感受：早该开始了。"
  },
  {
    "tag": "干货教程型",
    "prompt": "请写一篇小红书教程正文，教{目标人群}如何{具体技能}，正文分步骤讲解{步骤数}个步骤，每步一句操作要点，开头写学习收益，结尾提醒常见误区。",
    "usage": "适合化妆教程、软件操作、烹饪步骤类笔记",
    "example": "收益：学会这3步新手也能画出自然眉；步骤：①修眉②勾勒③填充；误区：别用力过猛。"
  },
  {
    "tag": "避坑警示型",
    "prompt": "请写一篇小红书正文，主题是{领域}新手常踩的{数量}个坑，用警示语气逐条列出，每条含坑点描述和正确做法，开头用一句提醒语，结尾鼓励收藏。",
    "usage": "适合装修、理财、求职、护肤等避坑指南笔记",
    "example": "开头：装修前必看，我踩过的5个坑！每条：坑一XX——正确做法是XX；结尾：建议收藏备用。"
  },
  {
    "tag": "开箱体验型",
    "prompt": "请写一篇小红书开箱正文，开箱{产品名称}，描述外观、手感、{核心功能}实际体验三方面，每方面一句真实感受，开头写入手原因，结尾给购买建议，语气真实不做作。",
    "usage": "适合数码、美妆、家居新品开箱笔记",
    "example": "入手原因：被颜值吸引；外观：磨砂质感高级；体验：续航给力；建议：性价比高可入。"
  },
  {
    "tag": "情绪共鸣型",
    "prompt": "请写一篇小红书正文，围绕{情绪主题}表达真实感受，开头用一句共鸣金句，正文分{数量}段递进抒发，每段不超过40字，结尾用一句温暖的话收尾，语气真诚细腻。",
    "usage": "适合情感、职场压力、生活方式类治愈笔记",
    "example": "开头：成年人的崩溃都是静音的；正文递进讲疲惫与自愈；结尾：你已经很棒了，慢慢来。"
  },
  {
    "tag": "提问互动型",
    "prompt": "请为{话题}写一篇小红书正文，开头抛出一个{目标人群}关心的疑问句，正文给出{数量}个观点或答案，每个观点一句说明，结尾再次提问引导评论区讨论。",
    "usage": "适合话题讨论、经验分享、观点输出类笔记",
    "example": "开头：25岁该不该裸辞？正文3个观点：看存款、看规划、看心态；结尾：你会怎么选？"
  },
  {
    "tag": "前后对比型",
    "prompt": "请写一篇小红书前后对比正文，主题是{改变主题}，正文分使用前状态、执行方法、使用后效果三部分描述，每部分配一句量化或具体描述，开头一句吸睛标题，结尾总结收获。",
    "usage": "适合减肥、护肤、收纳、改造类效果展示笔记",
    "example": "标题：30天腰围小5cm；前：裤子扣不上；方法：每天20分钟；后：轻松穿S码；收获：坚持有用。"
  }
]
